namespace MagicMiracleSetup {
static class SetupInfo {
 public const string AppName="magic&miracle",Version="1.4.1",ExeName="magic&miracle.exe",UninstallName="卸载 magic&miracle.exe",Marker="magic&miracle-install-v6";
 public const string RunKey="Software\\Microsoft\\Windows\\CurrentVersion\\Run",UninstallKey="Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\magic&miracle";
 public static string DefaultDir{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs",AppName);}}
 public static string ConfigDir{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),AppName);}}
 public static string DesktopLink{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),AppName+".lnk");}}
 public static string MenuDir{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),AppName);}}
 public static string Quote(string s){return Convert.ToChar(34)+s+Convert.ToChar(34);}
 public static void Extract(string resource,string path){using(Stream s=Assembly.GetExecutingAssembly().GetManifestResourceStream(resource)){if(s==null)throw new InvalidOperationException("安装资源缺失："+resource);using(var f=new FileStream(path,FileMode.Create,FileAccess.Write,FileShare.None))s.CopyTo(f);}}
 public static void Shortcut(string link,string target,string args,string work,string description){Directory.CreateDirectory(Path.GetDirectoryName(link));Type t=Type.GetTypeFromProgID("WScript.Shell");object shell=Activator.CreateInstance(t),shortcut=null;try{shortcut=t.InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{link});Type st=shortcut.GetType();st.InvokeMember("TargetPath",BindingFlags.SetProperty,null,shortcut,new object[]{target});st.InvokeMember("Arguments",BindingFlags.SetProperty,null,shortcut,new object[]{args??""});st.InvokeMember("WorkingDirectory",BindingFlags.SetProperty,null,shortcut,new object[]{work});st.InvokeMember("Description",BindingFlags.SetProperty,null,shortcut,new object[]{description});st.InvokeMember("IconLocation",BindingFlags.SetProperty,null,shortcut,new object[]{target+",0"});st.InvokeMember("Save",BindingFlags.InvokeMethod,null,shortcut,null);}finally{if(shortcut!=null&&Marshal.IsComObject(shortcut))Marshal.FinalReleaseComObject(shortcut);if(shell!=null&&Marshal.IsComObject(shell))Marshal.FinalReleaseComObject(shell);}}
 public static void RestoreCursor(){try{Native.SystemParametersInfo(0x57,0,IntPtr.Zero,0);}catch{}}
 public static void StopInstalled(){foreach(var p in Process.GetProcessesByName("magic&miracle"))try{p.CloseMainWindow();if(!p.WaitForExit(1200))p.Kill();}catch{}}
}

static class Native {[DllImport("user32.dll")]public static extern bool SystemParametersInfo(int a,int p,IntPtr d,int f);}

