 public InstallerForm(string initialDir){Text="安装 magic&miracle";ClientSize=new Size(720,490);FormBorderStyle=FormBorderStyle.FixedSingle;MaximizeBox=false;StartPosition=FormStartPosition.CenterScreen;BackColor=back;Font=new Font("Microsoft YaHei UI",9);try{Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);}catch{}
  var banner=new Panel{Location=new Point(0,0),Size=new Size(220,490),BackColor=side};Controls.Add(banner);var logo=LoadImage("SetupAvatar.jpg");var pic=new PictureBox{Image=logo,SizeMode=PictureBoxSizeMode.Zoom,Location=new Point(48,38),Size=new Size(124,124),BackColor=side};banner.Controls.Add(pic);banner.Controls.Add(new Label{Text="magic&miracle",UseMnemonic=false,Font=new Font("Segoe UI",15,FontStyle.Bold),ForeColor=Color.FromArgb(244,237,219),BackColor=side,TextAlign=ContentAlignment.MiddleCenter,Location=new Point(10,180),Size=new Size(200,34)});banner.Controls.Add(new Label{Text="六款造型 · 热键自适应",ForeColor=Color.FromArgb(176,190,180),BackColor=side,TextAlign=ContentAlignment.MiddleCenter,Location=new Point(10,216),Size=new Size(200,26)});banner.Controls.Add(new Label{Text="单文件安装程序\n版本 1.4.1",ForeColor=Color.FromArgb(160,176,164),BackColor=side,TextAlign=ContentAlignment.BottomCenter,Location=new Point(25,400),Size=new Size(170,48)});
  Controls.Add(new Label{Text="准备安装",Font=new Font("Microsoft YaHei UI",22,FontStyle.Bold),ForeColor=ink,BackColor=back,AutoSize=true,Location=new Point(254,30)});Controls.Add(new Label{Text="选择安装位置和启动方式，然后开始安装。",ForeColor=soft,BackColor=back,AutoSize=true,Location=new Point(257,78)});
  Controls.Add(new Label{Text="安装位置",Font=new Font("Microsoft YaHei UI",10,FontStyle.Bold),ForeColor=ink,BackColor=back,AutoSize=true,Location=new Point(258,124)});pathBox=new TextBox{Location=new Point(258,154),Size=new Size(348,30),Text=string.IsNullOrWhiteSpace(initialDir)?ExistingLocation():initialDir};Controls.Add(pathBox);var browse=new Button{Text="浏览…",Location=new Point(616,152),Size=new Size(74,32),FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(224,216,201),ForeColor=ink};browse.FlatAppearance.BorderSize=0;browse.Click+=Browse;Controls.Add(browse);
  startup=MakeCheck("登录 Windows 时自动启动（推荐）",258,218,true);desktop=MakeCheck("在桌面创建快捷方式",258,258,true);launch=MakeCheck("安装完成后立即运行",258,298,true);
  progress=new ProgressBar{Location=new Point(258,358),Size=new Size(432,8),Style=ProgressBarStyle.Continuous};Controls.Add(progress);status=new Label{Text="尚未开始",ForeColor=soft,BackColor=back,Location=new Point(258,375),Size=new Size(300,28)};Controls.Add(status);install=new Button{Text="开始安装",Font=new Font("Microsoft YaHei UI",10,FontStyle.Bold),ForeColor=Color.White,BackColor=green,FlatStyle=FlatStyle.Flat,Location=new Point(558,414),Size=new Size(132,44)};install.FlatAppearance.BorderSize=0;install.Click+=Install;Controls.Add(install);var cancel=new Button{Text="取消",ForeColor=ink,BackColor=Color.FromArgb(224,216,201),FlatStyle=FlatStyle.Flat,Location=new Point(462,414),Size=new Size(84,44)};cancel.FlatAppearance.BorderSize=0;cancel.Click+=delegate{Close();};Controls.Add(cancel);
 }
 Image LoadImage(string name){using(Stream s=Assembly.GetExecutingAssembly().GetManifestResourceStream(name)){if(s==null)return null;using(var temp=Image.FromStream(s))return new Bitmap(temp);}}
 CheckBox MakeCheck(string text,int x,int y,bool value){var c=new CheckBox{Text=text,Checked=value,AutoSize=true,Location=new Point(x,y),ForeColor=ink,BackColor=back};Controls.Add(c);return c;}
 string ExistingLocation(){try{using(var k=Registry.CurrentUser.OpenSubKey(SetupInfo.UninstallKey))if(k!=null){var v=k.GetValue("InstallLocation") as string;if(!string.IsNullOrEmpty(v))return v;}}catch{}return SetupInfo.DefaultDir;}
 void Browse(object sender,EventArgs e){using(var d=new FolderBrowserDialog()){d.Description="选择 magic&miracle 的安装文件夹";d.SelectedPath=pathBox.Text;if(d.ShowDialog(this)==DialogResult.OK)pathBox.Text=Path.Combine(d.SelectedPath,SetupInfo.AppName);}}
 void Install(object sender,EventArgs e){string dir;try{dir=Path.GetFullPath(Environment.ExpandEnvironmentVariables(pathBox.Text.Trim()));if(string.IsNullOrEmpty(dir)||Path.GetPathRoot(dir)==dir)throw new InvalidOperationException("不能直接安装到磁盘根目录。");}catch(Exception ex){MessageBox.Show(this,"安装位置无效："+ex.Message,"无法安装",MessageBoxButtons.OK,MessageBoxIcon.Warning);return;}install.Enabled=false;pathBox.Enabled=false;status.Text="正在复制程序…";progress.Value=10;Application.DoEvents();try{
   Directory.CreateDirectory(dir);string exe=Path.Combine(dir,SetupInfo.ExeName),tmp=exe+".new",uninstallPath=Path.Combine(dir,SetupInfo.UninstallName),marker=Path.Combine(dir,".magic-miracle-install");SetupInfo.StopInstalled();SetupInfo.RestoreCursor();SetupInfo.Extract("AppPayload.exe",tmp);if(File.Exists(exe))File.Delete(exe);File.Move(tmp,exe);if(!string.Equals(Path.GetFullPath(Application.ExecutablePath),Path.GetFullPath(uninstallPath),StringComparison.OrdinalIgnoreCase))File.Copy(Application.ExecutablePath,uninstallPath,true);File.WriteAllText(marker,SetupInfo.Marker,Encoding.UTF8);progress.Value=45;status.Text="正在创建快捷方式…";Application.DoEvents();
   if(desktop.Checked)SetupInfo.Shortcut(SetupInfo.DesktopLink,exe,"",dir,"启动 magic&miracle");else if(File.Exists(SetupInfo.DesktopLink))File.Delete(SetupInfo.DesktopLink);Directory.CreateDirectory(SetupInfo.MenuDir);SetupInfo.Shortcut(Path.Combine(SetupInfo.MenuDir,SetupInfo.AppName+".lnk"),exe,"",dir,"启动 magic&miracle");SetupInfo.Shortcut(Path.Combine(SetupInfo.MenuDir,"卸载 "+SetupInfo.AppName+".lnk"),uninstallPath,"/uninstall",dir,"卸载 magic&miracle");
   using(var k=Registry.CurrentUser.CreateSubKey(SetupInfo.RunKey)){if(startup.Checked)k.SetValue(SetupInfo.AppName,SetupInfo.Quote(exe)+" --minimized");else k.DeleteValue(SetupInfo.AppName,false);k.DeleteValue("CosmicChromeMouse",false);}progress.Value=70;status.Text="正在注册卸载信息…";Application.DoEvents();using(var k=Registry.CurrentUser.CreateSubKey(SetupInfo.UninstallKey)){k.SetValue("DisplayName",SetupInfo.AppName);k.SetValue("DisplayVersion",SetupInfo.Version);k.SetValue("Publisher","magic&miracle");k.SetValue("InstallLocation",dir);k.SetValue("DisplayIcon",exe+",0");k.SetValue("UninstallString",SetupInfo.Quote(uninstallPath)+" /uninstall");k.SetValue("QuietUninstallString",SetupInfo.Quote(uninstallPath)+" /uninstall /quiet");k.SetValue("NoModify",1,RegistryValueKind.DWord);k.SetValue("NoRepair",1,RegistryValueKind.DWord);k.SetValue("EstimatedSize",(int)(new FileInfo(exe).Length/1024),RegistryValueKind.DWord);}
   Directory.CreateDirectory(SetupInfo.ConfigDir);string settings=Path.Combine(SetupInfo.ConfigDir,"settings.ini");if(!File.Exists(settings))SetupInfo.Extract("DefaultSettings.ini",settings);progress.Value=100;status.Text="安装完成";install.Text="完成";install.Enabled=true;install.Click-=Install;install.Click+=delegate{if(launch.Checked)Process.Start(exe);Close();};MessageBox.Show(this,"magic&miracle 已安装完成。\n\n桌面图标和开始菜单入口已经创建。","安装完成",MessageBoxButtons.OK,MessageBoxIcon.Information);
  }catch(Exception ex){progress.Value=0;status.Text="安装失败";install.Enabled=true;pathBox.Enabled=true;MessageBox.Show(this,"安装失败：\n"+ex.Message,"magic&miracle 安装程序",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
}

static class Uninstaller {
 public static void Run(bool quiet){string dir=Path.GetFullPath(AppDomain.CurrentDomain.BaseDirectory.TrimEnd(Path.DirectorySeparatorChar)),marker=Path.Combine(dir,".magic-miracle-install");if(!File.Exists(marker)||File.ReadAllText(marker,Encoding.UTF8).IndexOf(SetupInfo.Marker,StringComparison.Ordinal)<0){if(!quiet)MessageBox.Show("未找到有效的安装标记，已停止卸载。","magic&miracle",MessageBoxButtons.OK,MessageBoxIcon.Warning);return;}if(!quiet&&MessageBox.Show("确定要卸载 magic&miracle 吗？","卸载确认",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;bool removeSettings=quiet||MessageBox.Show("是否同时删除个人设置？","卸载 magic&miracle",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes;try{SetupInfo.StopInstalled();SetupInfo.RestoreCursor();using(var k=Registry.CurrentUser.OpenSubKey(SetupInfo.RunKey,true)){if(k!=null){k.DeleteValue(SetupInfo.AppName,false);k.DeleteValue("CosmicChromeMouse",false);}}Registry.CurrentUser.DeleteSubKeyTree(SetupInfo.UninstallKey,false);Delete(SetupInfo.DesktopLink);Delete(Path.Combine(SetupInfo.MenuDir,SetupInfo.AppName+".lnk"));Delete(Path.Combine(SetupInfo.MenuDir,"卸载 "+SetupInfo.AppName+".lnk"));try{Directory.Delete(SetupInfo.MenuDir,false);}catch{}Delete(Path.Combine(dir,SetupInfo.ExeName));Delete(marker);if(removeSettings)try{string f=Path.Combine(SetupInfo.ConfigDir,"settings.ini");Delete(f);Directory.Delete(SetupInfo.ConfigDir,false);}catch{}string self=Application.ExecutablePath;var psi=new ProcessStartInfo("cmd.exe","/c ping 127.0.0.1 -n 2 > nul & del /f /q "+SetupInfo.Quote(self)+" & rmdir "+SetupInfo.Quote(dir)){CreateNoWindow=true,UseShellExecute=false,WindowStyle=ProcessWindowStyle.Hidden};Process.Start(psi);if(!quiet)MessageBox.Show("magic&miracle 已卸载。","卸载完成",MessageBoxButtons.OK,MessageBoxIcon.Information);}catch(Exception ex){if(!quiet)MessageBox.Show("卸载未完成：\n"+ex.Message,"卸载失败",MessageBoxButtons.OK,MessageBoxIcon.Error);}}
 static void Delete(string path){try{if(File.Exists(path))File.Delete(path);}catch{}}
}

static class Program {
 [STAThread]static void Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);bool uninstall=false,quiet=false;string dir=null;foreach(string a in args){if(string.Equals(a,"/uninstall",StringComparison.OrdinalIgnoreCase))uninstall=true;if(string.Equals(a,"/quiet",StringComparison.OrdinalIgnoreCase))quiet=true;if(a.StartsWith("/dir=",StringComparison.OrdinalIgnoreCase))dir=a.Substring(5).Trim().Trim(Convert.ToChar(34));}if(uninstall)Uninstaller.Run(quiet);else Application.Run(new InstallerForm(dir));}
}
